def parse_semver(version):
    '''
    Parses a semantic version string into a (major, minor, patch) tuple.

    Args:
        version: The semantic version string (e.g., '1.2.3', '0.5.0').

    Returns:
        A tuple of three integers: (major, minor, patch).

    Raises:
        ValueError: If the version string is not in a valid semantic version format.
    '''
    if not isinstance(version, str):
        raise TypeError('Version must be a string.')
    if not version:
        raise ValueError('Version string cannot be empty.')

    parts = version.split('.')

    if len(parts) != 3:
        raise ValueError(
            f'Invalid semantic version format: {version}. Expected three parts.'
        )

    try:
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])
    except ValueError as e:
        raise ValueError(
            f'Invalid semantic version format: {version}. Parts must be integers.'
        ) from e

    if not all(part >= 0 for part in [major, minor, patch]):
        raise ValueError(
            f'Invalid semantic version format: {version}. Version parts cannot be negative.'
        )

    return (major, minor, patch)

