import time
import math
import random

def retry_with_backoff(fn, attempts, *args, **kwargs):
    'Retries a callable with exponential backoff.'
    if not callable(fn):
        raise TypeError('`fn` must be a callable.')
    if not isinstance(attempts, int) or attempts < 1:
        raise ValueError('`attempts` must be a positive integer.')

    for i in range(attempts):
        try:
            return fn(*args, **kwargs)
        except Exception as e:
            if i == attempts - 1:
                raise e  # Re-raise the last exception if all attempts fail

            # Exponential backoff with jitter
            # Wait time = (2^i - 1) * 0.1 + random_jitter_ms
            # Base sleep in seconds, jitter in milliseconds
            base_sleep_s = (math.pow(2, i) - 1) * 0.1
            jitter_ms = random.uniform(0, 100)
            sleep_duration = base_sleep_s + (jitter_ms / 1000.0)
            time.sleep(sleep_duration)

    # This part should ideally not be reached if exceptions are re-raised or fn succeeds
    raise RuntimeError('Function failed after all retries without re-raising an exception.')
