def flatten_dict(d, sep='.'):
    '''
    Flattens a nested dictionary into a single-level dictionary.

    Args:
        d (dict): The dictionary to flatten.
        sep (str): The separator to use for concatenating keys. Defaults to '.'.

    Returns:
        dict: A new dictionary with flattened keys.

    Raises:
        TypeError: If the input d is not a dictionary.
    '''
    if not isinstance(d, dict):
        raise TypeError('Input d must be a dictionary.')

    flattened_items = {}

    def _flatten(obj, prefix=''):
        if isinstance(obj, dict):
            for key, value in obj.items():
                new_prefix = f'{prefix}{sep}{key}' if prefix else key
                _flatten(value, new_prefix)
        elif isinstance(obj, list):
            for index, item in enumerate(obj):
                new_prefix = f'{prefix}{sep}{index}' if prefix else str(index)
                _flatten(item, new_prefix)
        else:
            flattened_items[prefix] = obj

    _flatten(d)
    return flattened_items
