    if not isinstance(version, str):
        raise TypeError('Input version must be a string.')
    if not version:
        raise ValueError('Version string cannot be empty.')

    parts = version.split('.')

    if len(parts) != 3:
        raise ValueError(
            f'Invalid semantic version format: {version}. Expected 3 parts.'
        )

    try:
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])
    except ValueError as e:
        raise ValueError(
            f'Invalid semantic version format: {version}. Parts must be integers.'
        ) from e

    if not all(num >= 0 for num in [major, minor, patch]):
        raise ValueError(
            'Semantic version numbers (major, minor, patch) must be non-negative.'
        )

    return (major, minor, patch)

