import functools

def lru_cache_decorator(maxsize):
    'A simple LRU cache decorator.'

    if not isinstance(maxsize, int):
        raise TypeError('Expected maxsize to be an integer.')
    if maxsize < 0:
        raise ValueError('Expected maxsize to be a non-negative integer.')

    def decorator(func):
        cache = collections.OrderedDict()

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            # Create a hashable key from args and kwargs
            # This assumes that all args and kwargs are hashable
            key = args + tuple(sorted(kwargs.items()))

            if key in cache:
                # Move the accessed item to the end to mark it as recently used
                cache.move_to_end(key)
                return cache[key]
            else:
                result = func(*args, **kwargs)
                cache[key] = result

                if len(cache) > maxsize:
                    # Remove the least recently used item (the first one)
                    cache.popitem(last=False)
                return result
        return wrapper
    return decorator
