from collections import OrderedDict
import functools

def lru_cache_decorator(maxsize):
    'Simple LRU cache decorator with a fixed maxsize.'
    if not isinstance(maxsize, int) or maxsize <= 0:
        raise ValueError('Expected maxsize to be a positive integer')

    def decorator(func):
        cache = OrderedDict()

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            # Create a hashable key for the cache
            # This handles positional and keyword arguments
            key = args
            if kwargs:
                key += tuple(sorted(kwargs.items()))

            if key in cache:
                # Move the key to the end to mark it as recently used
                cache.move_to_end(key)
                return cache[key]
            else:
                result = func(*args, **kwargs)
                cache[key] = result
                # Remove the least recently used item if the cache is full
                if len(cache) > maxsize:
                    cache.popitem(last=False)  # popitem(last=False) removes the first (LRU) item
                return result
        return wrapper
    return decorator
