    try:
        major = int(components[0])
        minor = int(components[1])
        patch = int(components[2])
    except ValueError as e:
        raise ValueError(
            f"Invalid semantic version component in '{version}'. All components must be integers."
        ) from e

    if major < 0 or minor < 0 or patch < 0:
        raise ValueError(
            f"Invalid semantic version: '{version}'. Version components cannot be negative."
        )

    return (major, minor, patch)
