    if len(parts) != 3:
        raise ValueError(
            f'Invalid semantic version format: {version}. Expected three parts separated by dots.'
        )

    try:
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])
    except ValueError as e:
        raise ValueError(
            f'Invalid semantic version part. All parts must be integers: {version}'
        ) from e

    if not all(part >= 0 for part in [major, minor, patch]):
        raise ValueError(
            f'Invalid semantic version part. All parts must be non-negative: {version}'
        )

