def parse_semver(version):
    'Parses a semantic version string into a (major, minor, patch) tuple.'
    parts = version.split('.')
    major = int(parts[0])
    minor = int(parts[1])
    patch_and_rest = parts[2]

    # Handle cases like '1.2.3-alpha' or '1.2.3+build'
    if '-' in patch_and_rest:
        patch = int(patch_and_rest.split('-')[0])
    elif '+' in patch_and_rest:
        patch = int(patch_and_rest.split('+')[0])
    else:
        patch = int(patch_and_rest)

    return (major, minor, patch)
